/* Bank soal COMPOSING tingkat SULIT (3) dan SANGAT SULIT (4), gaya AcEPT UGM / tes menulis akademik.
 * Jenis: menyusun paragraf 5–6 kalimat, kalimat sumbang, posisi kalimat sisipan, konektor halus,
 * kalimat topik/penutup/pelengkap, menggabungkan kalimat, dan parafrase setara makna.
 * Helper ord() menghitung kunci urutan secara otomatis dari urutan benar + urutan tampil,
 * dan membuat pengecoh dengan menukar pasangan kalimat yang memang terikat penanda kohesi.
 */
const DASH = (a) => a.join('–');
function ord(correct, disp, e, swaps) {
  const shown = disp.map((i) => correct[i]);
  const seq = correct.map((_, k) => disp.indexOf(k) + 1);
  const key = DASH(seq);
  const wrong = [];
  const pairs = swaps || (correct.length === 5 ? [[0, 1], [2, 3], [3, 4]] : [[1, 2], [3, 4], [4, 5]]);
  for (const [a, b] of [...pairs, [0, 2], [1, 3], [2, 4], [0, 1], [1, 2]]) {
    if (b >= seq.length) continue;
    const s = seq.slice(); [s[a], s[b]] = [s[b], s[a]];
    const k2 = DASH(s);
    if (k2 !== key && !wrong.includes(k2)) wrong.push(k2);
    if (wrong.length === 3) break;
  }
  return { q: `Arrange the sentences into the most coherent paragraph.<br>${shown.map((s, i) => `(${i + 1}) ${s}`).join('<br>')}`, o: [key, ...wrong], a: 0, e: `${e} Urutan yang benar: ${key}.` };
}
const N5 = ['(1)', '(2)', '(3)', '(4)', '(5)'];
const odd = (sents, a, e) => ({ q: `Which sentence does <b>not</b> belong in the paragraph?<br>${sents.map((s, i) => `(${i + 1}) ${s}`).join('<br>')}`, o: N5, a, e, f: true });
const ins = (sent, p, a, e) => ({ q: `Where would the following sentence best fit in the paragraph?<br><b>${sent}</b><br>${p[0]} [1] ${p[1]} [2] ${p[2]} [3] ${p[3]} [4]`, o: ['[1]', '[2]', '[3]', '[4]'], a, e, f: true });
const CON = 'Choose the best word or phrase to complete the sentence.<br>';
const TOP = 'Choose the best topic sentence for the paragraph.<br>';
const END = 'Choose the best concluding sentence for the paragraph.<br>';
const MID = 'Choose the sentence that best completes the paragraph.<br>';
const CMB = 'Which sentence best combines the two sentences without changing their meaning?<br>';
const RST = 'Which sentence is closest in meaning to the original sentence?<br>';

